const catalog = [
  ['navigation.speedOverGround', 'Navigation', 'kn'], ['navigation.courseOverGroundTrue', 'Navigation', '°T'], ['navigation.position', 'Navigation', 'lat, lon'],
  ['environment.wind.speedApparent', 'Vent', 'kn'], ['environment.wind.angleApparent', 'Vent', '°'], ['environment.outside.temperature', 'Environnement', '°C'], ['environment.outside.pressure', 'Environnement', 'hPa'],
  ['propulsion.0.revolutions', 'Propulsion', 'tr/min'], ['propulsion.0.temperature', 'Propulsion', '°C'], ['electrical.batteries.house.voltage', 'Électricité', 'V']
];
const colors = ['#3ad8cf','#f1b94c','#ff7569','#a78bfa','#72a9ff','#f472b6'];
const state = { selected: new Set(['environment.wind.speedApparent','navigation.speedOverGround','electrical.batteries.house.voltage']), duration: 'PT24H', server: '', provider: '', data: [], paths: catalog, live: false };
const $ = (s) => document.querySelector(s);
const escapeHTML = (s) => String(s).replace(/[&<>'"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));

function label(path) { return path.split('.').slice(-1)[0].replace(/([A-Z])/g, ' $1').replace(/^./, x => x.toUpperCase()); }
function unit(path) { return (state.paths.find(x => x[0] === path) || [null,null,''])[2]; }
function nice(path) { return `${label(path)}${unit(path) ? ` · ${unit(path)}` : ''}`; }
function isoToLocal(date) { const pad=n=>String(n).padStart(2,'0'); return `${date.getFullYear()}-${pad(date.getMonth()+1)}-${pad(date.getDate())}T${pad(date.getHours())}:${pad(date.getMinutes())}`; }
function periodDates() { const from = $('#from-date').value, to = $('#to-date').value; if (from && to) return [new Date(from),new Date(to)]; const now = new Date(); let ms={PT15M:9e5,PT1H:36e5,PT24H:864e5,P7D:6048e5}[state.duration]||864e5; return [new Date(now-ms),now]; }
function setInitialDates() { const [from,to]=periodDates(); $('#from-date').value=isoToLocal(from); $('#to-date').value=isoToLocal(to); }

function renderPathList() {
  const q=$('#path-filter').value.trim().toLowerCase(); const groups={};
  state.paths.filter(p=>p[0].toLowerCase().includes(q)).forEach(p=>(groups[p[1]] ||= []).push(p));
  $('#path-list').innerHTML=Object.entries(groups).map(([group,paths])=>`<div class="path-group">${group}</div>${paths.map(([path,,u])=>`<label class="path-item"><input type="checkbox" data-path="${path}" ${state.selected.has(path)?'checked':''}/><span class="path-name">${path}</span><span class="path-unit">${u}</span></label>`).join('')}`).join('') || '<p style="color:var(--muted);font-size:13px">Aucun path trouvé.</p>';
  $('#selected-count').textContent=`${state.selected.size} sélectionnée${state.selected.size!==1?'s':''}`;
  document.querySelectorAll('[data-path]').forEach(el=>el.addEventListener('change',e=>{e.target.checked?state.selected.add(e.target.dataset.path):state.selected.delete(e.target.dataset.path); renderPathList(); renderAll();}));
}
function seeded(seed) { let x = seed % 2147483647; return () => (x=x*48271%2147483647)/2147483647; }
function demoData() {
  const [start,end]=periodDates(); const n=48, rng=seeded(start.getTime()/1e5); const paths=[...state.selected];
  return Array.from({length:n},(_,i)=>{const t=new Date(start.getTime()+(end-start)*i/(n-1)); const row={time:t.toISOString()}; paths.forEach((p,index)=>{let v;if(p.includes('wind.speed'))v=13+3*Math.sin(i/5)+rng()*1.6;if(p.includes('speedOver'))v=5.2+.8*Math.sin(i/7+1)+rng()*.55;if(p.includes('voltage'))v=12.8-.45*i/n+Math.sin(i/11)*.1;if(p.includes('pressure'))v=1015+5*Math.sin(i/17);if(p.includes('temperature'))v=18+2*Math.sin(i/13);if(p.includes('revolutions'))v=1200+420*Math.max(0,Math.sin(i/8));if(p.includes('angle'))v=120+65*Math.sin(i/6);if(p.includes('course'))v=(242+20*Math.sin(i/9)+360)%360;if(p==='navigation.position')v={latitude:48.39+i*.001,longitude:-4.49+i*.001}; row[p]=v ?? (index+1)*10+rng()*3;});return row;});
}
function format(path,value) { if(value==null)return '—'; if(typeof value==='object')return `${value.latitude?.toFixed(4)}, ${value.longitude?.toFixed(4)}`; let v=value,u=unit(path); if(path.includes('speed') && u==='kn')v=value*1.94384; if(path.includes('temperature') && u==='°C')v=value-273.15; if(path.includes('pressure') && u==='hPa')v=value/100; if(path.includes('revolutions'))v=value*60; if(path.includes('angle')||path.includes('course'))v=value*180/Math.PI; return `${v.toFixed(u==='tr/min'||u==='°'||u==='hPa'?0:1)}${u?` ${u}`:''}`; }
function numericValue(path,v){if(v==null)return null;if(typeof v==='object')return null;if(path.includes('speed')&&unit(path)==='kn')return v*1.94384;if(path.includes('temperature')&&unit(path)==='°C')return v-273.15;if(path.includes('pressure')&&unit(path)==='hPa')return v/100;if(path.includes('revolutions'))return v*60;if(path.includes('angle')||path.includes('course'))return v*180/Math.PI;return v;}
function renderChart() { const paths=[...state.selected], rows=state.data; const svg=$('#chart'), empty=$('#chart-empty'); svg.innerHTML=''; empty.hidden=paths.length>0; $('#legend').innerHTML=paths.map((p,i)=>`<span class="legend-item"><i class="legend-color" style="background:${colors[i%colors.length]}"></i>${escapeHTML(nice(p))}</span>`).join(''); $('#chart-caption').textContent=paths.length?`${paths.length} mesure${paths.length>1?'s':''} · ${rows.length} points`:'';
  if(!paths.length||!rows.length)return;
  const W=1000,H=360,pad=20; paths.forEach((path,index)=>{const vals=rows.map(r=>numericValue(path,r[path])).filter(Number.isFinite);if(!vals.length)return;const min=Math.min(...vals),max=Math.max(...vals),range=max-min||1;const points=rows.map((r,i)=>{const v=numericValue(path,r[path]);return v==null?null:[pad+i*(W-2*pad)/Math.max(rows.length-1,1),H-pad-(v-min)/range*(H-2*pad)]});let d='';points.forEach((p,i)=>{if(p)d+=(d?' L':'M')+p[0].toFixed(1)+' '+p[1].toFixed(1)});const area=d?`${d} L ${W-pad} ${H-pad} L ${pad} ${H-pad} Z`:'';svg.insertAdjacentHTML('beforeend',`<path class="chart-area" d="${area}" fill="${colors[index%colors.length]}"/><path class="chart-line" d="${d}" stroke="${colors[index%colors.length]}"/>`);});
  const f=new Intl.DateTimeFormat('fr-FR',{hour:'2-digit',minute:'2-digit',day:'2-digit',month:'2-digit'}); $('#axis-labels').innerHTML=[rows[0],rows[Math.floor(rows.length/2)],rows[rows.length-1]].map(r=>`<span>${f.format(new Date(r.time))}</span>`).join('');
}
function renderTable() { const paths=[...state.selected],rows=state.data; $('#table-head').innerHTML=`<tr><th>Horodatage</th>${paths.map(p=>`<th>${escapeHTML(label(p))}</th>`).join('')}</tr>`; const f=new Intl.DateTimeFormat('fr-FR',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit'}); $('#table-body').innerHTML=rows.slice().reverse().slice(0,30).map(r=>`<tr><td>${f.format(new Date(r.time))}</td>${paths.map(p=>`<td>${escapeHTML(format(p,r[p]))}</td>`).join('')}</tr>`).join('');$('#table-count').textContent=rows.length?`${rows.length} relevés`:''; }
function updateSummary() { const [a,b]=periodDates(); const hrs=(b-a)/36e5; $('#period-summary').textContent=hrs===24?'Dernières 24 heures':hrs<24?`Dernières ${hrs<1?Math.round(hrs*60)+' min':hrs+' heures'}`:`Du ${a.toLocaleDateString('fr-FR')} au ${b.toLocaleDateString('fr-FR')}`;$('#provider-summary').textContent=state.live?(state.provider||'Provider Signal K'):'Données de démonstration';$('#points-summary').textContent=state.data.length?`${state.data.length} × ${state.selected.size}`:'—'; }
function renderAll(){renderChart();renderTable();updateSummary();}
function toast(text){const n=$('#toast');n.textContent=text;n.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>n.classList.remove('show'),3200);}
async function loadHistory(){ if(!state.selected.size){state.data=[];renderAll();return;} $('#run-button').disabled=true;$('#run-button').textContent='Chargement…';$('#state-summary').textContent='Chargement';try {if(!state.live){state.data=demoData();}else{const [from,to]=periodDates();const agg=$('#aggregate').value;const paths=[...state.selected].map(p=>`${p}:${agg}`).join(',');const q=new URLSearchParams({from:from.toISOString(),to:to.toISOString(),paths});if($('#resolution').value)q.set('resolution',$('#resolution').value);if(state.provider)q.set('provider',state.provider);const res=await fetch(`${state.server}/signalk/v2/api/history/values?${q}`);if(!res.ok)throw new Error(`Erreur HTTP ${res.status}`);const result=await res.json();const columns=result?.paths?.map(p=>p.path)||[...state.selected];state.data=(result.data||[]).map(row=>Object.fromEntries([['time',row[0]],...columns.map((p,i)=>[p,row[i+1]])]));}renderAll();$('#state-summary').textContent='Prêt';toast(`${state.data.length} relevés chargés.`);}catch(e){$('#state-summary').textContent='Erreur';toast(`Impossible de charger l’historique : ${e.message}`);}finally{$('#run-button').disabled=false;$('#run-button').innerHTML='Actualiser les données <span>→</span>';}}
async function connect(){const raw=$('#server-url').value.trim().replace(/\/$/,'');if(!raw){state.live=false;state.server='';$('#connection-label').textContent='Mode démo';$('#connection-note').textContent='Les valeurs simulées permettent d’essayer l’interface.';loadHistory();return;}$('#connect-button').disabled=true;try{const url=`${raw}/signalk/v2/api/history/_providers`;const res=await fetch(url);if(!res.ok)throw new Error(`HTTP ${res.status}`);const providers=await res.json();state.server=raw;state.provider=Array.isArray(providers)?(providers[0]?.id||providers[0]||''):'';state.live=true;$('#connection-label').textContent='Connecté à Signal K';$('#connection-note').textContent=`History API v2 · ${state.provider||'provider par défaut'}`;try{const p=await fetch(`${raw}/signalk/v2/api/history/paths?duration=${state.duration}`);const paths=await p.json();if(Array.isArray(paths)&&paths.length){state.paths=paths.slice(0,300).map(x=>[x,x.split('.')[0],unit(x)]);}}catch(_){}renderPathList();await loadHistory();}catch(e){state.live=false;$('#connection-label').textContent='Connexion impossible';$('#connection-note').textContent='Vérifiez l’URL, CORS et un provider d’historique actif.';toast(`Connexion impossible : ${e.message}`);}finally{$('#connect-button').disabled=false;}}
function exportCsv(){const paths=[...state.selected];if(!state.data.length||!paths.length){toast('Aucune donnée à exporter.');return;}const quote=x=>`"${String(x).replaceAll('"','""')}"`;const rows=state.data.map(r=>[r.time,...paths.map(p=>typeof r[p]==='object'?JSON.stringify(r[p]):r[p]??'')].map(quote).join(','));const csv=[['timestamp',...paths].map(quote).join(','),...rows].join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='signalk-history.csv';a.click();URL.revokeObjectURL(a.href);}
document.addEventListener('DOMContentLoaded',()=>{setInitialDates();renderPathList();state.data=demoData();renderAll();$('#run-button').addEventListener('click',loadHistory);$('#connect-button').addEventListener('click',connect);$('#path-filter').addEventListener('input',renderPathList);$('#export-button').addEventListener('click',exportCsv);$('#clear-button').addEventListener('click',()=>{state.selected.clear();renderPathList();renderAll();});document.querySelectorAll('[data-duration]').forEach(b=>b.addEventListener('click',()=>{state.duration=b.dataset.duration;document.querySelectorAll('[data-duration]').forEach(x=>x.classList.toggle('active',x===b));setInitialDates();loadHistory();}));['from-date','to-date','resolution','aggregate'].forEach(id=>$('#'+id).addEventListener('change',loadHistory));if(!location.hostname.endsWith('chatgpt.site')){$('#server-url').value=location.origin;connect();}});
